import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import Breadcrumbs from '../../components/Breadcrumbs/Breadcrumbs';
import Gallery from '../../components/Gallery/Gallery';
import RatingTable from '../../components/RatingTable/RatingTable';
import LocationInfo from '../../components/LocationInfo/LocationInfo';
import YandexMap from '../../components/YandexMap/YandexMap';
import './VenuePage.css';

import likeIcon from '../../assets/icons/like.svg';
import heartFilledIcon from '../../assets/icons/heart2.svg';
import { favoritesService } from '../../utils/favorites';

const VenuePage = () => {
  const { id: establishmentId } = useParams();
  const [restaurant, setRestaurant] = useState(null);
  const [galleryImages, setGalleryImages] = useState([]);
  const [isFavorite, setIsFavorite] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadRestaurantData = async () => {
      setLoading(true);
      try {
        const response = await fetch(`http://localhost:8000/establishments/${establishmentId}`);
        if (response.ok) {
          const data = await response.json();
          setRestaurant(data);

          if (data.images) {
            try {
              const parsedImages = JSON.parse(data.images);
              setGalleryImages(parsedImages.map(img =>
                img.startsWith('/images/') ? '/assets' + img : img
              ));
            } catch {
              setGalleryImages([data.images]);
            }
          } else {
            setGalleryImages(['/assets/images/venue.jpg']);
          }
        }
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };

    loadRestaurantData();
  }, [establishmentId]);

  useEffect(() => {
    setIsFavorite(favoritesService.isFavorite(establishmentId));
  }, [establishmentId]);

  const toggleFavorite = () => {
    if (isFavorite) {
      favoritesService.remove(establishmentId);
      setIsFavorite(false);
    } else {
      favoritesService.add(establishmentId);
      setIsFavorite(true);
    }
  };

  if (loading) return <div className="loading">Загрузка ресторана...</div>;
  if (!restaurant) return <div className="loading">Ресторан не найден</div>;

  return (
    <div className="venue-page">
      <Breadcrumbs
        items={[
          { label: 'Каталог', path: '/catalog' },
          { label: restaurant.name, path: null }
        ]}
      />
      <div className="venue-container">
        <div className="venue-header">
          <h1 className="venue-title">{restaurant.name}</h1>
          <div className="rating">
            <img src="/assets/svg/star.svg" alt="Рейтинг" className="star-icon" />
            <span className="rating-value">{restaurant.rating?.toFixed(1)}</span>
          </div>
          <button onClick={toggleFavorite}>
            <img src={isFavorite ? heartFilledIcon : likeIcon} alt="" width="32" height="32"/>
          </button>
        </div>
        <Gallery images={galleryImages} />
      </div>

      <div className="venue-container">
        <p>{restaurant.description}</p>
        <RatingTable establishmentId={establishmentId} />
        <LocationInfo
          address={restaurant.address}
          phone={restaurant.contact_phone}
          email={restaurant.contact_email}
          hours={restaurant.open_hours}
        />
        <YandexMap address={restaurant.address} center={[55.7649, 37.6190]} zoom={16} />
      </div>
    </div>
  );
};

export default VenuePage;
